/**
 * Keeps the README's static HUD excerpt honest.
 *
 * The README shows a frame of the HUD as text. It is generated by `demo.mjs --markdown` from
 * the same timeline as the GIF, but nothing stops someone editing the HUD and leaving the
 * excerpt behind — at which point the docs advertise a layout the code no longer renders.
 *
 * This asserts the excerpt in README.md is exactly what the demo produces now. When it fails,
 * regenerate rather than hand-edit:
 *
 *   node scripts/demo.mjs braille --markdown   # copy the output into README.md
 */
import { execFileSync } from "node:child_process";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, resolve } from "node:path";
import assert from "node:assert/strict";

const here = dirname(fileURLToPath(import.meta.url));
const root = resolve(here, "..");

// `--markdown` emits its own ``` fence so it can be pasted straight into a document; the
// README stores the same content inside its own fence. Compare the inner text of both.
const stripFence = (text) => text.replace(/^```\n/, "").replace(/\n?```\s*$/, "");
const generated = stripFence(
  execFileSync(process.execPath, [resolve(here, "demo.mjs"), "braille", "--markdown"], {
    cwd: root,
    encoding: "utf8",
  }).trimEnd(),
);

const readme = readFileSync(resolve(root, "README.md"), "utf8");
const anchor = readme.indexOf("<summary>A static frame, as text</summary>");
assert.ok(anchor >= 0, "README.md must contain a static frame excerpt");

const open = readme.indexOf("```", anchor);
assert.ok(open >= 0, "the excerpt must be a fenced code block");
const close = readme.indexOf("```", open + 3);
assert.ok(close > open, "the excerpt's code fence must be closed");
const embedded = readme.slice(open + 3, close).replace(/^\n/, "").trimEnd();

if (embedded !== generated) {
  const a = embedded.split("\n");
  const b = generated.split("\n");
  const firstDiff = a.findIndex((line, i) => line !== b[i]);
  console.error("README's HUD excerpt has drifted from the demo.\n");
  console.error(`  README line ${firstDiff + 1}:`);
  console.error(`    ${JSON.stringify(a[firstDiff] ?? "<missing>")}`);
  console.error(`  demo.mjs produces:`);
  console.error(`    ${JSON.stringify(b[firstDiff] ?? "<missing>")}`);
  console.error("\nRegenerate with:  node scripts/demo.mjs braille --markdown");
}

assert.equal(embedded, generated, "README HUD excerpt must match scripts/demo.mjs output");
console.log(`README HUD excerpt matches the demo (${generated.split("\n").length} lines)`);